`,af="g3-pack-1",cf="G3 事件包：34 条，覆盖猫/狗/兔/通用与八种 kind；字段与质量门槛见 docs/v4.5-parallel-development/g3/CONTENT-PACK-SCHEMA.md。",df=JSON.parse('[{"id":"CAT-DAILY-001","kind":"daily","title":"窗台上的下午","scene":"下午三点的光斜着铺在地板上，窗框的影子慢慢挪过茶几。它跳上窗台，尾巴搭在窗框边缘，楼下收废品的三轮车经过，铃铛响了一声。它耳朵转了转，没有回头看你，只是把前爪往前收了收。","species":["cat"],"stage":"any","requires":{"minDay":1},"weight":30,"cooldownDays":40,"maxPerRun":2,"choices":[{"id":"A","label":"搬椅子陪它坐一会儿","detail":"什么也不做，就一起看窗外。会占掉一点精力。","cost":{"money":0,"energy":4,"timeHours":0.5},"effect":{"trust":6,"mood":5,"stress":-4},"outcome":"你把椅子搬到窗边，坐下时地板响了一下。它没有动，过了很久才把后背靠向你这侧的窗框。光从地板退到墙角时，你们谁都没有说话。","risk":"choice"},{"id":"B","label":"先去把该做的事做完","detail":"今天还有一堆事。它会自己待着。","cost":{"money":0,"energy":0,"timeHours":0},"effect":{"trust":-2,"stress":3},"outcome":"你转身进了里屋。晚上回来时窗台已经空了，垫子上还留着一个温热的窝。你伸手摸了摸，它从沙发底下看着你，没有出来。","risk":"choice"},{"id":"C","label":"拿逗猫棒把它引下来","detail":"它本来在休息，陪玩会让它兴奋，也会打断这份安静。","cost":{"money":0,"energy":6,"timeHours":0.5},"effect":{"mood":4,"trust":2,"stress":2},"outcome":"你甩了两下羽毛，它盯了很久，突然从窗台扑下来，把逗猫棒按在爪下。之后它在客厅跑了两圈，又回到窗台，呼吸比刚才快。","risk":"choice"}],"evidence":{"sourceIds":[],"fictionIds":["g2-turns-fiction"]}},{"id":"CAT-AUTONOMY-002","kind":"autonomy","title":"桌上的东西","scene":"客厅传来一声轻响。你过去看时，它正坐在桌边，前爪悬在桌沿，一支笔滚到地上。它看着你，又把另一支笔慢慢推下去，眼睛一直没有离开你，尾巴在桌面上轻轻扫。","species":["cat"],"stage":"young","requires":{"minDay":12},"weight":20,"cooldownDays":25,"maxPerRun":3,"choices":[{"id":"A","label":"把桌上的东西收进抽屉","detail":"桌子空了，它就没得推了。","cost":{"money":0,"energy":3,"timeHours":0.5},"effect":{"stress":-2,"mood":-1,"trust":-1},"outcome":"你把笔、钥匙和零钱一件件收进抽屉。它坐在旁边看，等桌子空了，跳下去，把地上的两支笔拨到沙发底下。","risk":"choice"},{"id":"B","label":"在桌边放一个空纸盒","detail":"给它一个能推、能钻的东西。","cost":{"money":2,"energy":2,"timeHours":0.25},"effect":{"mood":4,"trust":2,"stress":-2},"outcome":"你找了个空纸盒放在桌边。它先闻，再伸爪进去掏，掏了半天，最后整只钻进去，把盒子压塌了一角，桌子上的东西没再动。","risk":"choice"},{"id":"C","label":"不管它，让它推","detail":"反正都是些小东西。","cost":{"money":0,"energy":0,"timeHours":0},"effect":{"mood":2,"stress":1},"outcome":"你回房间继续做事。外面每隔一会儿响一声，像在报时。第二天早上，你在沙发底下找到三支笔、一个瓶盖和你的钥匙。","risk":"choice"}],"evidence":{"sourceIds":[],"fictionIds":["g2-turns-fiction"]}},{"id":"CAT-TURN-001","kind":"turn","title":"凌晨四点的跑酷","scene":"凌晨四点，走廊里传来爪子打滑的声音。它从客厅一头冲到另一头，撞翻了垃圾桶，塑料袋哗啦作响。你睁开眼，看见它停在卧室门口，瞳孔在暗处放大，尾巴尖一抖一抖，像是在等你追。","species":["cat"],"stage":"young","requires":{"minDay":5},"weight":22,"cooldownDays":25,"maxPerRun":3,"choices":[{"id":"A","label":"起来陪它跑十分钟","detail":"用鞋带逗它扑几轮，把多余的力气耗掉。今晚的睡眠会少一点。","cost":{"money":0,"energy":6,"timeHours":0.5},"effect":{"trust":4,"mood":6,"stress":-3},"outcome":"你光脚站在地板上，用一根鞋带逗它来回扑。十分钟后它躺倒在毯子上，肚子起伏，没再跑。你回床上时天还没亮，它跟进来，睡在床脚。","risk":"choice"},{"id":"B","label":"把卧室门关上","detail":"明天还要早起，今晚先顾自己。","cost":{"money":0,"energy":0,"timeHours":0},"effect":{"trust":-3,"stress":2},"outcome":"门关上的瞬间，外面安静了几秒，接着是爪子挠门的声音，断断续续。你睡着了。早上开门时，它坐在门口，脚边是一只被咬扁的纸团。","risk":"choice"},{"id":"C","label":"干脆起来做点事","detail":"反正睡不着了。你在客厅待着，它自己玩。","cost":{"money":0,"energy":4,"timeHours":1},"effect":{"stress":-2,"trust":1,"mood":-3},"outcome":"你泡了杯茶，坐在沙发上看它自己玩。它把纸团推到你脚边，等你踢，你没有动，它就自己追着纸团跑。天亮时你们都困了。","risk":"choice"}],"evidence":{"sourceIds":[],"fictionIds":["g2-turns-fiction"]}},{"id":"CAT-AUTONOMY-001","kind":"autonomy","title":"藏起来的袜子","scene":"洗完衣服，你发现少了一只袜子。找了半天，最后在沙发底下看见它：袜子被团成一小团，压在它前爪下面。它趴得很低，下巴贴着地板，眼睛一眨不眨地盯着你，尾巴尖轻轻扫着灰。","species":["cat"],"stage":"kitten","requires":{"minDay":10},"weight":20,"cooldownDays":30,"maxPerRun":2,"choices":[{"id":"A","label":"趴下来伸手够","detail":"跟它抢一次，看谁先松爪。","cost":{"money":0,"energy":2,"timeHours":0},"effect":{"trust":2,"mood":4,"stress":-2},"outcome":"你趴在地板上，手指刚碰到袜角，它就往后缩了半米，又把袜子叼回来一点。来回几次，你干脆把袜子让给它，它叼着战利品钻进了纸箱。","risk":"choice"},{"id":"B","label":"留一只旧袜子给它","detail":"把落单的那只给它，省得它总来翻抽屉。","cost":{"money":0,"energy":1,"timeHours":0},"effect":{"mood":5,"trust":2},"outcome":"你从抽屉里翻出一只落单的旧袜子，放在纸箱口。它探出头闻了闻，把新袜子拖进去。第二天，沙发底下又多了两只，其中一只是你的。","risk":"choice"},{"id":"C","label":"把沙发挪开清理","detail":"底下积了不少灰，顺便把失踪的东西都找出来。","cost":{"money":0,"energy":8,"timeHours":1},"effect":{"stress":-4,"mood":-2,"trust":-1},"outcome":"你一个人把沙发推开，底下全是灰尘、发圈和失踪很久的袜子。它站在旁边看，等你清完，马上把其中一只重新拖回角落。","risk":"choice"}],"evidence":{"sourceIds":[],"fictionIds":["g2-turns-fiction"]}},{"id":"CAT-ACCIDENT-001","kind":"accident","title":"纱窗没扣紧","scene":"傍晚起风，窗子开着一条缝。它跳上窗台，前爪搭在纱窗上，纱窗轻轻往外鼓了一下，底下的卡扣没有扣上。楼下有小孩在追跑，声音传上来，它的尾巴压低了，喉咙里发出很轻的咔咔声。","species":["cat"],"stage":"any","requires":{"minDay":20},"weight":14,"cooldownDays":0,"maxPerRun":1,"choices":[{"id":"A","label":"关窗并请人换纱窗","detail":"花一笔钱把卡扣换成结实的，约师傅上门。","cost":{"money":20,"energy":4,"timeHours":2},"effect":{"stress":-6,"trust":2},"outcome":"你把它从窗台抱下来，关了窗，当天约了师傅。第二天新纱窗装好，卡扣很紧。它在窗台上闻了很久，才重新趴下。","setFlags":["fixed-screen","window-handled"],"followUp":{"eventId":"CAT-CHAIN-001","afterDays":24},"risk":"choice"},{"id":"B","label":"先用胶带贴住缝隙","detail":"先对付一晚，等周末再说。","cost":{"money":2,"energy":2,"timeHours":0.5},"effect":{"stress":-2},"outcome":"你剪了几段胶带，把纱窗四边贴住。它蹲在旁边看你操作，胶带撕开的声音让它耳朵一直动。贴完后它试了两下，纱窗没再动。","setFlags":["taped-screen","window-handled"],"followUp":{"eventId":"CAT-CHAIN-001","afterDays":18},"risk":"choice"},{"id":"C","label":"先把它抱进里屋","detail":"窗子关着，它今天别上窗台了。","cost":{"money":0,"energy":2,"timeHours":0},"effect":{"trust":-2,"mood":-3,"stress":-2},"outcome":"你关了窗，把它抱进卧室。它在门口坐了一会儿，又回到窗边，隔着玻璃看楼下。那天下午它没有再上窗台。","setFlags":["window-handled"],"followUp":{"eventId":"CAT-CHAIN-001","afterDays":30},"risk":"choice"}],"evidence":{"sourceIds":[],"fictionIds":["g2-turns-fiction"]}},{"id":"CAT-WONDER-001","kind":"wonder","title":"第一场雪","scene":"夜里下雪，早上窗外白了一层。它第一次看见雪，蹲在窗台上，鼻子几乎贴上玻璃。一片雪打在窗上，它缩了一下脖子，随即伸出前爪去拍，只拍到冰凉的玻璃。","species":["cat"],"stage":"any","requires":{"minDay":1},"weight":10,"cooldownDays":60,"maxPerRun":1,"choices":[{"id":"A","label":"开一条窗缝让它闻","detail":"冷风会灌进来，屋里会凉一阵。","cost":{"money":0,"energy":1,"timeHours":0},"effect":{"mood":4,"trust":2,"stress":-1},"outcome":"你把窗推开两指宽，冷风灌进来。它伸长脖子闻了很久，胡须上沾了一点水汽，然后打了个喷嚏，退回垫子上。","risk":"choice"},{"id":"B","label":"抱它到阳台看","detail":"让它离雪近一点，但它可能怕冷。","cost":{"money":0,"energy":4,"timeHours":0.5},"effect":{"trust":3,"mood":3,"stress":2},"outcome":"你抱着它站在阳台门口。雪落在它背上，它抖了一下，爪子抓紧你的袖子。不到一分钟你就把它抱回屋里，它在暖气边舔了很久的毛。","risk":"choice"},{"id":"C","label":"拍张照，继续做早饭","detail":"留个纪念就好，日子照常过。","cost":{"money":0,"energy":0,"timeHours":0},"effect":{"mood":-1},"outcome":"你拍了张照，它在照片里只留下一个背影。等早饭做好，窗台上已经空了，玻璃上留着两个湿的爪印。","risk":"choice"}],"evidence":{"sourceIds":[],"fictionIds":["g2-turns-fiction"]}},{"id":"CAT-SENIOR-001","kind":"daily","title":"老猫的午睡路线","scene":"它平常从沙发扶手跳上窗台，再沿着书柜走到暖气旁的垫子。今天它在沙发边停了两次，落地时前脚一歪，趴下以后呼吸还比平时急。你放下手里的杯子，蹲在离它两步远的地方。","species":["cat"],"stage":"senior","requires":{"minDay":30},"weight":18,"cooldownDays":35,"maxPerRun":2,"choices":[{"id":"A","label":"联系医院，清出平地","detail":"说明落脚和呼吸的变化，给出门留出路。","cost":{"money":5,"energy":3,"timeHours":0.5},"effect":{"trust":3,"mood":4,"stress":-3},"outcome":"你马上打给医院，说清它落脚和呼吸的变化。听院方安排时，家人搬开了挡路的木凳，把卷起的地垫铺平。你看着它的耳朵朝声音转了一下。","risk":"choice"},{"id":"B","label":"联系医院，把垫子放低","detail":"把熟悉的垫子移到它走平地能到的地方。","cost":{"money":0,"energy":2,"timeHours":0.5},"effect":{"mood":2,"trust":1,"stress":-4},"outcome":"你立刻联系医院，照院方指示准备出门。家人把它常用的垫子放到平地，又移开挡路的纸袋。你起身时，它还在原来的地方，你继续和院方确认安排。","risk":"choice"},{"id":"C","label":"请家人准备外出用品","detail":"你留在旁边，马上打给医院。","cost":{"money":0,"energy":6,"timeHours":0},"effect":{"trust":4,"mood":3,"stress":1},"outcome":"你立刻打给医院，说清它刚才脚下一歪、趴着时还喘得急。家人把外出用品放到门边，两人照院方的安排准备出发。暖气旁的旧垫子仍空着。","risk":"choice"}],"evidence":{"sourceIds":["SRC-CAND-CONTENT-PDSA-CAT-BREATHING","SRC-CAND-CONTENT-CATS-PROTECTION-SENIOR"],"fictionIds":["g2-turns-fiction"]}},{"id":"CAT-KITTEN-001","kind":"daily","title":"第一次剪指甲","scene":"你把它放在腿上，手里捏着指甲剪。它先是好奇地闻了闻，接着看见自己的前爪被捏住，整只猫突然僵住，后腿蹬了两下，尾巴飞快地甩。阳光照在它爪尖上，指甲还是透明的，像一层薄薄的壳。","species":["cat"],"stage":"kitten","requires":{"minDay":7},"weight":16,"cooldownDays":45,"maxPerRun":1,"choices":[{"id":"A","label":"一次只剪一只","detail":"剪完就放，明天再剪另一只。","cost":{"money":0,"energy":4,"timeHours":0.5},"effect":{"trust":2,"stress":-1,"mood":1},"outcome":"你剪完一只前爪就松手，它立刻窜到沙发背后。半小时后它自己出来，蹭了蹭你的手。第二天你剪另一只，它没有第一次那么僵。","risk":"choice"},{"id":"B","label":"用毛巾裹住再剪","detail":"快是快，但它会记住这件事。","cost":{"money":0,"energy":6,"timeHours":0.5},"effect":{"trust":-3,"stress":5,"mood":-2},"outcome":"你用毛巾把它裹成一个卷，只露出前爪。剪到第三只时它开始低声叫，剪完你松开，它躲进床底，晚饭时才出来。","risk":"choice"},{"id":"C","label":"今天先不剪","detail":"只摸摸爪子，让它习惯被碰。","cost":{"money":0,"energy":1,"timeHours":0},"effect":{"trust":4,"mood":2,"stress":-2},"outcome":"你捏了捏它的爪垫，又松开，反复几次。它从你腿上跳下去，走了两步，又回来用头蹭你的膝盖。指甲剪被你放回了抽屉。","risk":"choice"}],"evidence":{"sourceIds":[],"fictionIds":["g2-turns-fiction"]}},{"id":"CAT-MULTIPET-001","kind":"multipet","title":"同一个纸箱","scene":"快递箱还留在客厅中央。先来的那只已经占住了，蜷成一只面包；后来的那只绕着箱子走了两圈，抬起前爪搭在边缘，往里探头。两双眼睛都盯着你，谁也没有先动。","species":["cat"],"stage":"any","requires":{"minDay":10,"minAnimals":2,"relation":["getting-acquainted","settled"]},"weight":26,"cooldownDays":30,"maxPerRun":2,"choices":[{"id":"A","label":"再找个箱子分开","detail":"两个都有，谁也不欠谁。","cost":{"money":0,"energy":2,"timeHours":0.5},"effect":{"mood":4,"stress":-3,"trust":1},"outcome":"你把第二个箱子放在窗边。两只各占一个，隔着一米半互相看。夜里你起来喝水，发现后来的那只睡在了第一个箱子的外侧。","followUp":{"eventId":"CAT-CHAIN-002","afterDays":400},"setFlags":["box-shared"],"risk":"choice"},{"id":"B","label":"让它们自己谈","detail":"不插手，看它们怎么解决。","cost":{"money":0,"energy":0,"timeHours":0},"effect":{"stress":4,"trust":1,"mood":2},"outcome":"低吼持续了十几秒，然后先来的那只起身走开，跳上了沙发。后来的那只钻进箱子，转了两圈才趴下。第二天早上，它们挤在同一个箱子里。","followUp":{"eventId":"CAT-CHAIN-002","afterDays":730},"setFlags":["box-shared"],"risk":"risk"},{"id":"C","label":"把箱子收走","detail":"省得它们为这个争。","cost":{"money":0,"energy":1,"timeHours":0},"effect":{"trust":-2,"mood":-3,"stress":2},"outcome":"你把箱子拆了，扔到门口。两只都在原地站了一会儿，先后走开。那天下午它们各自睡在屋子两头，没有打架，也没有靠近。","risk":"choice"}],"evidence":{"sourceIds":[],"fictionIds":["g2-turns-fiction"]}},{"id":"CAT-CHAIN-001","kind":"chain","title":"窗台外的喜鹊","scene":"纱窗处理过之后，窗台成了它每天的位置。楼下那棵树上落了一只喜鹊，黑白分明，叫得很响。它把身体压得很低，尾巴一下一下抽动，喉咙里发出细碎的咔咔声，前爪在窗台上反复踩。","species":["cat"],"stage":"any","requires":{"minDay":20,"flags":["window-handled"]},"weight":1,"cooldownDays":0,"maxPerRun":1,"choices":[{"id":"A","label":"在窗边装一块猫爬板","detail":"让它有地方看树，也离玻璃远一点。","cost":{"money":12,"energy":5,"timeHours":1},"effect":{"mood":5,"stress":-4,"trust":2},"outcome":"你在窗边固定了一块窄木板，刚好够它趴着看树。装好的第一个下午它就上去了，一看就是两个小时。喜鹊再来时，它只是甩了甩尾巴。","risk":"choice"},{"id":"B","label":"拉上纱帘挡住视线","detail":"看不见就不激动，但窗台也没意思了。","cost":{"money":0,"energy":1,"timeHours":0},"effect":{"mood":-3,"stress":-3,"trust":-1},"outcome":"你把纱帘拉上。它在帘子后面坐了很久，最后走开，去睡了。之后几天它很少再上窗台，喜鹊还是每天叫。","risk":"choice"},{"id":"C","label":"带它到楼下看树","detail":"换个地方看，但要抱它出门。","cost":{"money":0,"energy":6,"timeHours":1},"effect":{"trust":3,"mood":3,"stress":3},"outcome":"你抱着它下楼，走近那棵树。喜鹊先飞走了，它在你怀里绷紧，四处看，耳朵一直朝声音转。回家后它在窗台上蹲到天黑。","risk":"choice"}],"evidence":{"sourceIds":[],"fictionIds":["g2-turns-fiction"]}},{"id":"CAT-CHAIN-002","kind":"chain","title":"又一个纸箱","scene":"新的快递箱又放在客厅中央，尺寸和当年差不多。两只都比当年安静了，走路也慢了些。先来的那只先闻到，绕着箱子转了一圈，没有进去，只是站在旁边看后来的那只。","species":["cat"],"stage":"any","requires":{"minDay":400,"minAnimals":2,"flags":["box-shared"]},"weight":1,"cooldownDays":0,"maxPerRun":1,"choices":[{"id":"A","label":"把箱子留下，不插手","detail":"它们有自己的规矩。","cost":{"money":0,"energy":0,"timeHours":0},"effect":{"mood":3,"trust":2,"stress":-2},"outcome":"后来的那只先钻进去，转了两圈趴下。先来的那只在箱子边站了一会儿，最后把头搁在箱沿上，两只就那么待着，谁也没让谁。","risk":"choice"},{"id":"B","label":"在箱子里铺一块旧毯子","detail":"让这个箱子闻起来像家。","cost":{"money":0,"energy":1,"timeHours":0},"effect":{"mood":4,"trust":3,"stress":-3},"outcome":"你铺了一块洗得发白的旧毯子。两只都在箱子边闻了很久，后来一只进去，另一只也挤进去，箱子被撑得变了形，谁都没有出来。","risk":"choice"},{"id":"C","label":"把箱子收起来","detail":"家里已经够挤了。","cost":{"money":0,"energy":2,"timeHours":0.5},"effect":{"mood":-2,"trust":-1},"outcome":"你把箱子折好放进储物间。那天下午两只都睡在沙发上，隔着半个坐垫。晚上你听见它们先后走进储物间，在纸箱旁边站了一会儿。","risk":"choice"}],"evidence":{"sourceIds":[],"fictionIds":["g2-turns-fiction"]}},{"id":"DOG-DAILY-001","kind":"daily","title":"门口的拖鞋","scene":"你加班回家，钥匙刚插进锁孔，门里就传来爪子抓地板的声音。门一开，它叼着一只拖鞋站在玄关，尾巴甩得整个后半身都在动。拖鞋上全是牙印，是上周你随手放在门口的那只。","species":["dog"],"stage":"adult","requires":{"minDay":1},"weight":26,"cooldownDays":30,"maxPerRun":3,"choices":[{"id":"A","label":"蹲下来接过来摸摸头","detail":"在玄关多待一会儿。","cost":{"money":0,"energy":3,"timeHours":0.25},"effect":{"trust":6,"mood":5,"stress":-5},"outcome":"你接过拖鞋，它顺势把脑袋塞进你手心，鼻尖是凉的。你在玄关蹲了一会儿，它把整个身体的重量都靠过来，尾巴慢慢停下来。","risk":"choice"},{"id":"B","label":"先换鞋洗手","detail":"它等一会儿就好。","cost":{"money":0,"energy":0,"timeHours":0},"effect":{"trust":-1,"mood":-2,"stress":1},"outcome":"你绕过它去换鞋，它跟在后面，拖鞋一直叼在嘴里。等你坐到沙发上，它才把拖鞋放在你脚边，自己趴下，下巴搁在鞋面上。","risk":"choice"},{"id":"C","label":"把拖鞋收进鞋柜","detail":"别再让它咬了。","cost":{"money":0,"energy":2,"timeHours":0.25},"effect":{"trust":-1,"mood":-1},"outcome":"你把拖鞋放进鞋柜，关上门。它在柜门前坐了一会儿，用鼻子拱了两下，然后去叼来另一只。第二天，鞋柜门被它用爪子扒开了一条缝。","risk":"choice"}],"evidence":{"sourceIds":[],"fictionIds":["g2-turns-fiction"]}},{"id":"DOG-TURN-001","kind":"turn","title":"雨天的散步","scene":"雨从早上开始下，路面泛着光。你拿起牵引绳，它立刻站起来，尾巴摇了两下，走到门口却停住了。楼道口积了一小片水，它低头闻了闻，抬脚又放下，回头看你，耳朵往后贴着。","species":["dog"],"stage":"any","requires":{"minDay":3},"weight":22,"cooldownDays":20,"maxPerRun":3,"choices":[{"id":"A","label":"抱着它绕过水坑","detail":"省得它踩湿，但你的裤腿要遭殃。","cost":{"money":0,"energy":8,"timeHours":0.5},"effect":{"trust":4,"mood":4,"stress":-2},"outcome":"你把它抱过那段积水，放下时它甩了甩毛，溅了你一裤腿。走出两条街它才放松，鼻子贴着湿掉的树根闻个不停。回家时你们都得擦一遍。","risk":"choice"},{"id":"B","label":"换到地下车库走","detail":"淋不到雨，但没有树和草地。","cost":{"money":0,"energy":4,"timeHours":1},"effect":{"mood":3,"trust":2,"stress":-1},"outcome":"你带它绕到地下车库。水泥地有回声，它走得很慢，每一步都低头闻。走到第三圈它才抬腿，尾巴重新摇起来。","risk":"choice"},{"id":"C","label":"回家玩找零食","detail":"不出门了，在屋里消耗精力。","cost":{"money":0,"energy":5,"timeHours":0.5},"effect":{"mood":3,"trust":1,"stress":-3},"outcome":"你把牵引绳挂回门后，它看着你，坐了下来。你在客厅藏了几粒狗粮，它一间一间找过去，找到最后一粒时，雨还没停。","risk":"choice"}],"evidence":{"sourceIds":[],"fictionIds":["g2-turns-fiction"]}},{"id":"DOG-ACCIDENT-001","kind":"accident","title":"半块巧克力","scene":"你回家时，茶几上的巧克力少了一半，包装纸被撕成几片。它趴在沙发边，嘴角还有一点褐色的痕迹，看见你时摇了摇尾巴，又低下头。你想起那块巧克力是昨晚放在这里的，具体被吃掉多少并不确定。","species":["dog"],"stage":"any","requires":{"minDay":15},"weight":12,"cooldownDays":0,"maxPerRun":1,"choices":[{"id":"A","label":"立刻带它去急诊","detail":"花一笔钱，搭进去一个下午。","cost":{"money":30,"energy":8,"timeHours":3},"effect":{"stress":6},"outcome":"你打电话过去，对方问清它的体重、吃了什么、大概什么时候，让你带上包装过去。你蹲下拿起那张皱掉的包装纸。上车以后，你才发现手里还一直攥着它。检查和观察用了一下午。","setFlags":["chocolate-incident"],"followUp":{"eventId":"DOG-CHAIN-001","afterDays":14},"risk":"choice"},{"id":"B","label":"先打电话问清楚","detail":"先问清楚情况，再带它过去。","cost":{"money":10,"energy":3,"timeHours":1},"effect":{"stress":3},"outcome":"电话里对方问得很细，让你先别喂东西，带上包装和它现在的情况过去。你挂掉电话就出门，到院后拿着包装，把电话里说过的时间又确认了一遍。","setFlags":["chocolate-incident"],"followUp":{"eventId":"DOG-CHAIN-001","afterDays":14},"risk":"choice"},{"id":"C","label":"立即打电话问急诊","detail":"拿着包装，请家人一起听院方怎么安排。","cost":{"money":0,"energy":0,"timeHours":0},"effect":{"stress":5,"trust":-1},"outcome":"你立刻拨通急诊电话，照着包装回答院方的问题。你说不准它是什么时候碰到的，家人就在旁边记下院方的指示，开始联系能接送的车。","setFlags":["chocolate-incident"],"followUp":{"eventId":"DOG-CHAIN-001","afterDays":7},"risk":"fate"}],"evidence":{"sourceIds":["SRC-CAND-CONTENT-PDSA-DOG-CHOCOLATE"],"fictionIds":["g2-turns-fiction"]}},{"id":"DOG-WONDER-001","kind":"wonder","title":"第一次见海","scene":"车停在堤坝下，海风把它的耳朵吹得翻过去。它先站在车门边不动，鼻子抬起来，对着风闻了很久，然后试探着往前走了几步。浪打上来，它往后跳了一下，又凑过去，前爪在湿沙上按出一个坑。","species":["dog"],"stage":"adult","requires":{"minDay":30},"weight":9,"cooldownDays":90,"maxPerRun":1,"choices":[{"id":"A","label":"松开长绳让它跑","detail":"海边空，但得看住它。","cost":{"money":0,"energy":6,"timeHours":1},"effect":{"mood":8,"trust":4,"stress":-6},"outcome":"它沿着浪线跑出去很远，又折回来，绕着你转圈，爪子上全是沙。海水漫过它的脚背时，它停住，低头闻了闻水面，然后打了个喷嚏。","risk":"choice"},{"id":"B","label":"牵着它慢慢走","detail":"不跑远，就在湿沙上走一段。","cost":{"money":0,"energy":3,"timeHours":1},"effect":{"mood":5,"trust":3,"stress":-4},"outcome":"你收短牵引绳，沿着湿沙走。它一直低着头，闻海藻、贝壳和别的狗留下的气味，走得很慢。回去的路上它在后座睡着了，身上还是咸的。","risk":"choice"},{"id":"C","label":"抱它到水边","detail":"让它离浪近一点，它可能会怕。","cost":{"money":0,"energy":8,"timeHours":0.5},"effect":{"stress":5,"mood":2,"trust":-2},"outcome":"你把它抱到水边，浪一到它就挣扎，爪子在你手臂上划出几道红印。你把它放下，它跑回干沙上抖了很久，之后只肯远远看着海。","risk":"choice"}],"evidence":{"sourceIds":[],"fictionIds":["g2-turns-fiction"]}},{"id":"DOG-SENIOR-001","kind":"daily","title":"慢下来的散步","scene":"以前它能跑到公园尽头。今天走到街角，它右后脚落地时一晃，停下后呼吸也比往常费力。你收短手里的牵绳，停在平地上。台阶就在前面，它抬起脚，又放了下来。","species":["dog"],"stage":"senior","requires":{"minDay":30},"weight":18,"cooldownDays":35,"maxPerRun":2,"choices":[{"id":"A","label":"停下散步，联系医院","detail":"留在平地上，说清步态和呼吸的变化。","cost":{"money":0,"energy":3,"timeHours":0.5},"effect":{"mood":3,"trust":3,"stress":-3},"outcome":"你停在平地上，立刻给医院打电话，说清它怎么落脚、停下后怎么喘。它把鼻尖贴在你裤脚上，你按院方的安排准备去看诊。","risk":"choice"},{"id":"B","label":"联系兽医，准备去医院","detail":"描述刚才的步态和呼吸，听院方安排。","cost":{"money":20,"energy":4,"timeHours":2},"effect":{"stress":0,"trust":2},"outcome":"你立刻联系医院，按院方安排带它过去。医生问起它停下后呼吸的样子，你把从街角到台阶的经过讲了一遍。出门时，它把头搁在你肩上。","risk":"choice"},{"id":"C","label":"请家人准备平地通道","detail":"你先打给医院，请家人收好门口杂物。","cost":{"money":0,"energy":5,"timeHours":1},"effect":{"mood":4,"trust":2,"stress":-2},"outcome":"你立刻打给医院，请家人把门口的杂物挪开，固定好防滑垫，给接送留出一条平路。挂电话时，它还站在你身旁，你按院方指示安排出发。","risk":"choice"}],"evidence":{"sourceIds":["SRC-FN-004","SRC-CAND-CONTENT-PDSA-DOG-LIMPING","SRC-CAND-CONTENT-PDSA-BREATHING"],"fictionIds":["g2-turns-fiction"]}},{"id":"DOG-MULTIPET-001","kind":"multipet","title":"两个饭盆","scene":"晚饭时间，你把两个饭盆放在厨房两头。先来的那只已经吃完了，还站在后来的那只的盆边，低着头看。后来的那只伏低身体，一边吃一边从眼角盯着它，尾巴夹着，碗里的粮食没怎么动。","species":["dog"],"stage":"any","requires":{"minDay":15,"minAnimals":2,"relation":["getting-acquainted","settled"]},"weight":24,"cooldownDays":25,"maxPerRun":2,"choices":[{"id":"A","label":"把它们分到两个房间","detail":"各吃各的，但门要关一会儿。","cost":{"money":0,"energy":3,"timeHours":0.5},"effect":{"stress":-3,"trust":1,"mood":1},"outcome":"你把后来的那只连盆端进卧室，关上门。它吃得很慢，吃到一半还抬头看门。门外那只趴在门口，鼻子贴着门缝。","risk":"choice"},{"id":"B","label":"站在中间看着吃完","detail":"你在场，它们会收敛一点。","cost":{"money":0,"energy":2,"timeHours":0.5},"effect":{"trust":2,"stress":-2,"mood":2},"outcome":"你站在两个盆中间，谁靠近就抬手挡一下。两只都吃完了，先来的那只舔了舔嘴，走开去喝水。后来的那只等你蹲下才把最后几口吃完。","risk":"choice"},{"id":"C","label":"只留一个盆，让它们排顺序","detail":"省事，但有一只可能要饿着等。","cost":{"money":0,"energy":0,"timeHours":0},"effect":{"stress":5,"trust":-2,"health":-2},"outcome":"你把两个盆并成一个。先来的那只先吃，后来的那只在旁边等，等到一半时试图靠近，被低吼了一声，退回去。之后几天它都等对方吃完才吃。","risk":"risk"}],"evidence":{"sourceIds":[],"fictionIds":["g2-turns-fiction"]}},{"id":"DOG-CHAIN-001","kind":"chain","title":"复查那天","scene":"复查约在周三下午。候诊室里有一只猫在叫，它坐在你脚边，牵引绳绕了一圈。护士叫到名字时它站起来，尾巴低低地摇，走到诊室门口又回头看了你一眼。","species":["dog"],"stage":"any","requires":{"minDay":7,"flags":["chocolate-incident"]},"weight":1,"cooldownDays":0,"maxPerRun":1,"choices":[{"id":"A","label":"把这段时间的变化说清楚","detail":"哪天吐过、哪天开始肯吃饭，都说。","cost":{"money":0,"energy":3,"timeHours":1},"effect":{"trust":3,"stress":-3,"health":2},"outcome":"你把能想起的都说了：哪天吐过、哪天开始肯吃饭、夜里起来几次。医生边听边记，最后说先按现在这样观察，两周后再看。","risk":"choice"},{"id":"B","label":"让它自己走两步给医生看","detail":"让医生看看它现在怎么走。","cost":{"money":0,"energy":2,"timeHours":0.5},"effect":{"trust":2,"stress":-2,"health":2},"outcome":"医生把它带到走廊，看它走了一个来回。它走得比平时慢，但在瓷砖上没打滑。医生蹲下来摸了摸它的后腿，说先不用做更多检查。","risk":"choice"},{"id":"C","label":"问清楚以后要注意什么","detail":"把该记的都记下来。","cost":{"money":10,"energy":4,"timeHours":1.5},"effect":{"trust":3,"stress":-4,"health":2},"outcome":"你问了饮食、散步和家里的地面。医生一条条说完，你在手机备忘录里记下。回家路上它把头搁在车窗边，看着外面。","risk":"choice"}],"evidence":{"sourceIds":[],"fictionIds":["g2-turns-fiction"]}},{"id":"RAB-DAILY-001","kind":"daily","title":"早晨的干草","scene":"早上七点，光线刚爬上窗台。它蹲在草架前，前爪搭在笼边，鼻子快速抽动。你把新干草塞进去，它立刻凑过来，一口一口地拽，草茎从嘴角支出来。吃到一半，它忽然侧躺下去，四条腿伸直，眼睛还睁着。","species":["rabbit"],"stage":"adult","requires":{"minDay":1},"weight":26,"cooldownDays":30,"maxPerRun":3,"choices":[{"id":"A","label":"蹲下来看它躺多久","detail":"什么也不做，就在旁边待着。","cost":{"money":0,"energy":2,"timeHours":0.25},"effect":{"trust":5,"mood":4,"stress":-3},"outcome":"你在笼边蹲了一会儿。它躺了不到一分钟，翻起来，又去拽草。你伸手摸了摸它的背，它没有躲，耳朵转了个方向。","risk":"choice"},{"id":"B","label":"趁它吃草清理笼底","detail":"它吃它的，你干你的。","cost":{"money":0,"energy":6,"timeHours":0.5},"effect":{"stress":-4,"mood":1,"trust":-1},"outcome":"你趁它吃草换了垫料。它对你的手很警惕，吃两口就抬头看，直到你退开才继续。清完之后它绕着笼子跑了一圈，在干净的角落趴下。","risk":"choice"},{"id":"C","label":"添几片绿叶菜","detail":"换换口味，但干草才是正餐。","cost":{"money":2,"energy":1,"timeHours":0.25},"effect":{"mood":5,"stress":-1},"outcome":"你洗了几片菜叶，甩干水递进去。它先闻，再小口咬，吃得很慢。它吃完又回到草架前，牵出一根干草。","risk":"choice"}],"evidence":{"sourceIds":["SRC-FN-010"],"fictionIds":["g2-turns-fiction"]}},{"id":"RAB-TURN-001","kind":"turn","title":"纸箱啃出门","scene":"你给它搭的纸箱城堡放在墙角，侧面本来只有一个小窗。今天你发现窗被啃大了一圈，边缘的纸板翻着毛边，地上落了一层纸屑。它从洞里探出头，鼻子上还沾着一点纸屑，看你一眼，又缩回去，里面传来抓挠声。","species":["rabbit"],"stage":"young","requires":{"minDay":5},"weight":22,"cooldownDays":25,"maxPerRun":2,"choices":[{"id":"A","label":"再给它一个纸箱接成通道","detail":"让它有得啃、有得钻。","cost":{"money":3,"energy":4,"timeHours":0.5},"effect":{"mood":7,"stress":-5,"trust":3},"outcome":"你找来一个旧纸箱，剪开门，和原来的接在一起。它先在新通道里走了两个来回，然后开始跑，纸箱被撞得直晃。那天下午它没再啃墙角的踢脚线。","setFlags":["box-tunnel","box-adjusted"],"followUp":{"eventId":"RAB-CHAIN-001","afterDays":12},"risk":"choice"},{"id":"B","label":"收起破掉的那只纸箱","detail":"换个开口完整的箱子，保持退路畅通。","cost":{"money":0,"energy":2,"timeHours":0.25},"effect":{"mood":-3,"stress":3,"trust":-1},"outcome":"你把破纸箱和地上的碎片一并收走，换上一个没有胶带的纸箱。它沿着外侧走了半圈，从另一个开口钻进去，过一会儿又探出了头。","followUp":{"eventId":"RAB-CHAIN-001","afterDays":20},"setFlags":["box-adjusted"],"risk":"choice"},{"id":"C","label":"换成一个木窝","detail":"结实，但气味和触感都变了。","cost":{"money":25,"energy":5,"timeHours":1},"effect":{"mood":-4,"stress":4,"trust":-2},"outcome":"你把纸箱拆了，换成一个木窝。它在木窝门口站了很久，不肯进去，最后趴在窝旁边。第二天早上，你发现木窝的角落被啃出一个浅浅的牙印。","followUp":{"eventId":"RAB-CHAIN-001","afterDays":30},"setFlags":["box-adjusted"],"risk":"choice"}],"evidence":{"sourceIds":["SRC-FN-007","SRC-FN-008"],"fictionIds":["g2-turns-fiction"]}},{"id":"RAB-AUTONOMY-001","kind":"autonomy","title":"半夜的跺脚","scene":"凌晨两点，客厅传来一声闷响，像是有人在敲地板。你开灯，看见它站在笼子中央，前爪并拢，后腿绷紧，又跺了一下。窗外有只野猫走过，影子从窗帘下扫过去。它的耳朵转向窗户，鼻子不停地动。","species":["rabbit"],"stage":"any","requires":{"minDay":10},"weight":18,"cooldownDays":25,"maxPerRun":2,"choices":[{"id":"A","label":"起来拉严窗帘","detail":"挡住外面的影子，你今晚也别想睡整觉了。","cost":{"money":0,"energy":3,"timeHours":0.5},"effect":{"stress":-4,"trust":2,"mood":1},"outcome":"你把窗帘拉严，又开了一盏小灯。它在笼子里站了一会儿，慢慢趴下，但耳朵还朝着窗户。你在沙发上坐到它闭上眼睛才回房。","risk":"choice"},{"id":"B","label":"把笼子挪到里墙","detail":"离窗户远一点，动静会小些。","cost":{"money":0,"energy":6,"timeHours":1},"effect":{"stress":-5,"mood":2,"trust":1},"outcome":"你把笼子和草架一起搬到里墙。它跟着笼子转了两圈，进去闻了闻，没再跺脚。第二天早上，窗外那串爪印还在。","risk":"choice"},{"id":"C","label":"不理它，继续睡","detail":"它跺一会儿就停了。","cost":{"money":0,"energy":0,"timeHours":0},"effect":{"stress":3,"mood":-2,"trust":-1},"outcome":"你关了灯。跺脚声又响了两次，间隔越来越长，后来停了。早上你去看，它趴在笼子最里面的角落，食盆里的草没怎么动。","risk":"choice"}],"evidence":{"sourceIds":[],"fictionIds":["g2-turns-fiction"]}},{"id":"RAB-ACCIDENT-001","kind":"accident","title":"从沙发上跳下来","scene":"它蹲在沙发靠背上，后腿试了两次，还是跳了下去。落地时身体歪了一下，右后腿没有踩实，接着它缩到茶几底下，蹲着不动。你伸手过去，它没有跑，只是把身体压得更低，鼻子快速地抽动。","species":["rabbit"],"stage":"young","requires":{"minDay":7},"weight":13,"cooldownDays":0,"maxPerRun":1,"choices":[{"id":"A","label":"联系能看兔的医院","detail":"路远、花钱，但把判断交给医生。","cost":{"money":25,"energy":8,"timeHours":3},"effect":{"stress":5},"outcome":"你打电话过去，说明了跳的高度和它现在的样子，对方让你把它放进航空箱，垫上毛巾，尽快过去。路上它一直缩在角落，没有出声。","followUp":{"eventId":"RAB-CHAIN-002","afterDays":14},"setFlags":["rabbit-checkup"],"risk":"choice"},{"id":"B","label":"立刻打电话说明经过","detail":"告诉医院它落地后的样子，按院方安排出门。","cost":{"money":0,"energy":3,"timeHours":1},"effect":{"stress":3,"trust":1},"outcome":"你立刻联系能看兔的医院，说清它落地后没踩实。按院方的安排，你马上带它出门。到院后，医生接过航空箱，问你是在哪儿看到它落地的。","followUp":{"eventId":"RAB-CHAIN-002","afterDays":21},"setFlags":["rabbit-checkup"],"risk":"choice"},{"id":"C","label":"请家人联系医院","detail":"你留在茶几旁，家人去打电话。","cost":{"money":0,"energy":2,"timeHours":0.5},"effect":{"stress":6,"trust":-3},"outcome":"你坐在离茶几一段距离的地板上，听见家人在门口报地址。它还缩在原处。电话结束后，你们按院方的安排准备出门。","followUp":{"eventId":"RAB-CHAIN-002","afterDays":7},"setFlags":["rabbit-checkup"],"risk":"fate"}],"evidence":{"sourceIds":["SRC-FN-007","SRC-CAND-CONTENT-PDSA-RABBIT-LIMPING"],"fictionIds":["g2-turns-fiction"]}},{"id":"RAB-SENIOR-001","kind":"daily","title":"晒太阳的位置","scene":"它现在大部分时间都待在阳台那块阳光里。上午十点，光从栏杆间漏下来，它侧躺在地砖上，后腿伸得很直，耳朵搭在脑后。风把晾着的衣服吹动，影子在它身上来回扫，它只是眨了一下眼。","species":["rabbit"],"stage":"senior","requires":{"minDay":30},"weight":18,"cooldownDays":35,"maxPerRun":2,"choices":[{"id":"A","label":"把垫子挪到阳光里","detail":"地砖凉，垫子软一点。","cost":{"money":0,"energy":2,"timeHours":0.25},"effect":{"trust":3,"mood":4,"stress":-3,"health":1},"outcome":"你把旧垫子铺到光斑的位置。它挪过去，闻了闻，趴下，把下巴搁在垫子边缘。下午光移走时，它跟着挪了半米，又在新的光里躺下。","risk":"choice"},{"id":"B","label":"抱它回屋","detail":"怕阳台风大，但它可能不领情。","cost":{"money":0,"energy":4,"timeHours":0.25},"effect":{"trust":-2,"mood":-2,"stress":-2},"outcome":"你把它抱回客厅。它在门边站了一会儿，又慢慢走回阳台，在原来的位置趴下。你没有再抱它，只是把阳台门关小了一点。","risk":"choice"},{"id":"C","label":"在阳台陪它坐一会儿","detail":"什么也不做，就待着。","cost":{"money":0,"energy":3,"timeHours":0.5},"effect":{"trust":4,"mood":3,"stress":-4},"outcome":"你搬了张凳子在阳台坐下。它没有起来，只是耳朵转向你。风把它的胡须吹动，你们一起待到光从栏杆上移开。","risk":"choice"}],"evidence":{"sourceIds":[],"fictionIds":["g2-turns-fiction"]}},{"id":"RAB-MULTIPET-001","kind":"multipet","title":"两只兔的躲避屋","scene":"躲避屋只有一个入口。先来的那只蹲在里面，只露出鼻子；后来的那只在门口转圈，用头顶了两下屋壁，纸板发出闷响。两只都没有叫，只有爪子刮过地砖的声音，和草架被碰动的轻响。","species":["rabbit"],"stage":"any","requires":{"minDay":10,"minAnimals":2,"relation":["getting-acquainted","settled"]},"weight":24,"cooldownDays":25,"maxPerRun":2,"choices":[{"id":"A","label":"再加一个躲避屋","detail":"各有一个，但占地方。","cost":{"money":15,"energy":3,"timeHours":0.5},"effect":{"mood":5,"stress":-5,"trust":2},"outcome":"你把第二个躲避屋放在笼子另一头。后来的那只先钻进去，又出来，在两个屋子之间来回跑了几趟。晚上你去看，两只各占一个，门口都朝向草架。","risk":"choice"},{"id":"B","label":"换成两个出口的屋子","detail":"有进有出，不容易被堵住。","cost":{"money":8,"energy":4,"timeHours":0.5},"effect":{"mood":4,"stress":-4,"trust":3},"outcome":"你换了一个两头通的纸箱。先来的那只从这头进去，从另一头出来，后来的那只跟在后面。两只在通道里挤了一下，各自退开，又重新走了一遍。","risk":"choice"},{"id":"C","label":"先看着，不动","detail":"让它们自己找位置。","cost":{"money":0,"energy":1,"timeHours":0.25},"effect":{"stress":2,"mood":2,"trust":1},"outcome":"你在笼边站着。后来的那只试了几次，最后挤进屋子的一角，先来的那只往里让了让，两只贴在一起，屋子被撑得鼓起来。之后它们没再分开。","risk":"risk"}],"evidence":{"sourceIds":["SRC-FN-007","SRC-FN-008"],"fictionIds":["g2-turns-fiction"]}},{"id":"RAB-CHAIN-001","kind":"chain","title":"贴地的纸箱路","scene":"整理活动区后，你发现墙边的纸箱又被啃出个缺口。它从这里钻出来时，箱底在地砖上挪了一下。下午的光铺到墙脚，它停在缺口边，鼻尖朝着亮处动了两下。","species":["rabbit"],"stage":"any","requires":{"minDay":20,"flags":["box-adjusted"]},"weight":1,"cooldownDays":0,"maxPerRun":1,"choices":[{"id":"A","label":"把纸箱固定在防滑垫上","detail":"让出入口贴着地面，两头都留空。","cost":{"money":10,"energy":5,"timeHours":1},"effect":{"mood":5,"trust":3,"stress":-4},"outcome":"你把箱底放平，用防滑垫稳住纸箱，再把两端的纸屑扫开。它顺着贴地的通道走到阳光里，转过身，把前爪收在胸前。","risk":"choice"},{"id":"B","label":"收起破纸箱，留一条平路","detail":"清走松散的纸板，保留原来的躲避处。","cost":{"money":0,"energy":3,"timeHours":0.5},"effect":{"mood":-4,"stress":3,"trust":-2},"outcome":"你把破纸箱收走，把墙边的防滑垫铺平。它在原箱的位置闻了一圈，沿着地面绕回旧窝，坐在出口朝光的那一侧。","risk":"choice"},{"id":"C","label":"在地上布置休息角","detail":"铺平防滑垫，给休息角留出两个方向。","cost":{"money":5,"energy":3,"timeHours":0.5},"effect":{"mood":4,"trust":2,"stress":-3},"outcome":"你把垫子铺在地面有阳光的地方，挪开两侧的东西。它沿着墙边绕过来，两脚踩上垫子，转了半圈才趴下，耳朵朝你转了一下。","risk":"choice"}],"evidence":{"sourceIds":["SRC-FN-007","SRC-FN-008"],"fictionIds":["g2-turns-fiction"]}},{"id":"RAB-CHAIN-002","kind":"chain","title":"复查之后","scene":"复查回来第三天，它开始在沙发前转圈。今天它又蹲在靠背上，后腿试了两次。这一次落地很稳，右后腿踩实了，它停了一秒，径直走向食盆，草架被碰得轻轻响。","species":["rabbit"],"stage":"any","requires":{"minDay":7,"flags":["rabbit-checkup"]},"weight":1,"cooldownDays":0,"maxPerRun":1,"choices":[{"id":"A","label":"把沙发前的旧垫子留下","detail":"它跳下来时有个缓冲，也省得你每次都盯着。","cost":{"money":0,"energy":2,"timeHours":0.25},"effect":{"mood":3,"trust":2,"stress":-2},"outcome":"你把旧垫子铺在沙发前。它跳下来时踩在垫子上，停了停，低头闻了闻，然后在垫子上趴下，后腿伸到一边。","risk":"choice"},{"id":"B","label":"把沙发前的杂物清空","detail":"给它一条干净的落地路线。","cost":{"money":0,"energy":4,"timeHours":0.5},"effect":{"mood":2,"trust":2,"stress":-3},"outcome":"你把茶几挪开半米，地上只剩一块空地。它跳下来时没有停顿，落地后跑了两步，又折回来，在空地上转了一圈。","risk":"choice"},{"id":"C","label":"暂时还抱它下来","detail":"再稳一点再说，但每次都要你动手。","cost":{"money":0,"energy":4,"timeHours":0.25},"effect":{"mood":-2,"trust":-1,"stress":2},"outcome":"它蹲在靠背上等了一会儿，你伸手把它抱下来。它在你怀里挣了一下，落地后走到食盆边，草没怎么动。","risk":"choice"}],"evidence":{"sourceIds":[],"fictionIds":["g2-turns-fiction"]}},{"id":"ANY-LIFE-001","kind":"life","title":"房东说要涨租","scene":"房东站在门口没进来，手指在门框上敲了两下。他说下个月起每月多两百，说完往里屋看了一眼——它正窝在沙发扶手上，身体随着呼吸轻轻起伏。你手里还攥着没拆的快递。","species":"any","stage":"any","requires":{"minDay":60,"notFlags":["moved-house","shared-home"]},"weight":18,"cooldownDays":0,"maxPerRun":1,"choices":[{"id":"A","label":"搬到更远但便宜的房子","detail":"通勤变长，但每月能省下一笔。需要一笔搬家钱。","cost":{"money":30,"energy":8,"timeHours":3},"effect":{"stress":8,"housing":"far-flat"},"outcome":"搬家那天下着小雨。新房子朝北，窗台比原来窄。它花了两天才找到能晒太阳的位置，第三天开始在窗台上睡午觉。","setFlags":["moved-house"],"followUp":{"eventId":"ANY-CHAIN-001","afterDays":3},"risk":"choice"},{"id":"B","label":"接下来多接一份活","detail":"房租照付，用加班把它补回来。","cost":{"money":0,"energy":12,"timeHours":2},"effect":{"money":40,"stress":10,"trust":-3},"outcome":"你连着两周在深夜回家。它开始在门口等，听到钥匙声才回去睡。饭盆有时剩一半，水碗边落着灰。","setFlags":["overworked"],"followUp":{"eventId":"ANY-CHAIN-002","afterDays":365},"risk":"choice"},{"id":"C","label":"找个室友一起分担","detail":"家里多一个人，也多个照应。","cost":{"money":5,"energy":3,"timeHours":1},"effect":{"stress":-6,"trust":2,"housing":"shared-home"},"outcome":"新室友搬进来那天，它躲在沙发底下看了两个小时。晚饭时桌上多了两个碗，它开始挨个凑近裤脚，最后选了一个人，趴在他脚边。","setFlags":["shared-home"],"followUp":{"eventId":"ANY-CHAIN-002","afterDays":300},"risk":"choice"}],"evidence":{"sourceIds":[],"fictionIds":["g2-turns-fiction"]}},{"id":"ANY-LIFE-002","kind":"life","title":"你换了夜班","scene":"排班表贴在冰箱上，夜班那一栏被红笔圈了出来。夜班每月多七百，白天能空出一整块时间；但晚上十一点到早上七点，屋子里只有它。你站在冰箱前，它在脚边转来转去，偶尔停下来看你。","species":"any","stage":"any","requires":{"minDay":45,"notFlags":["night-shift"]},"weight":16,"cooldownDays":0,"maxPerRun":1,"choices":[{"id":"A","label":"接下夜班","detail":"钱多一截，但晚上它一个人在家。","cost":{"money":0,"energy":10,"timeHours":2},"effect":{"money":50,"stress":8,"trust":-2},"outcome":"第一个夜班回家时天刚亮。它睡在门口，听见开门声才醒，站起来伸了个懒腰。白天你补觉，它趴在你床边，偶尔用鼻子碰你的手。","setFlags":["night-shift"],"followUp":{"eventId":"ANY-CHAIN-002","afterDays":365},"risk":"choice"},{"id":"B","label":"留在白班，钱紧一点","detail":"日子照旧，账要算得更细。","cost":{"money":10,"energy":2,"timeHours":0.5},"effect":{"stress":3,"trust":3,"mood":3},"outcome":"你跟主管说不排夜班。那个月的账算得很紧，买菜时你多看了几眼价签。它还是照旧在傍晚等你，饭碗里没缺过。","risk":"choice"},{"id":"C","label":"和家里人轮流照看","detail":"多一个人搭手，也得多欠一份人情。","cost":{"money":5,"energy":4,"timeHours":1},"effect":{"stress":-2,"trust":1,"mood":1},"outcome":"你和家里人排了个班。有人晚上过来陪它，也有人白天带它出门。它渐渐把两个住处都当成自己的，只是每次换地方，头一晚都睡不踏实。","risk":"choice"}],"evidence":{"sourceIds":[],"fictionIds":["g2-turns-fiction"]}},{"id":"ANY-LIFE-003","kind":"life","title":"一张修车账单","scene":"修车行打来电话，说变速箱要换，报价比你这个月的结余多出不少。你坐在楼梯口，手机贴在耳边，屋里的它把玩具从沙发推到地上，又推了一次，声音一下一下传下来。","species":"any","stage":"any","requires":{"minDay":90},"weight":15,"cooldownDays":0,"maxPerRun":1,"choices":[{"id":"A","label":"先修车，把它的年检往后推","detail":"车不能没有，年检可以往后拖。","cost":{"money":60,"energy":5,"timeHours":2},"effect":{"stress":12,"health":-3},"outcome":"你把车留在修车行，走路回家。它照旧在门口等你，只是你回来得比平时晚。宠物医院的年检预约还留在手机日历里，你没有删。","setFlags":["skipped-checkup"],"followUp":{"eventId":"ANY-CHAIN-002","afterDays":400},"risk":"choice"},{"id":"B","label":"先不修，改坐公交","detail":"每天多花四十分钟，换一笔不欠人的账。","cost":{"money":8,"energy":8,"timeHours":2},"effect":{"stress":6,"mood":-2},"outcome":"你开始坐公交上班，每天多花四十分钟。它很快适应了新的出门时间，只是下雨天你到家时，鞋总是湿的。","risk":"choice"},{"id":"C","label":"跟朋友借一笔钱","detail":"车先修好，人情慢慢还。","cost":{"money":10,"energy":3,"timeHours":1},"effect":{"stress":10,"mood":-4},"outcome":"朋友把钱转过来，说什么时候还都行。你买了新的变速箱，也补上了这个月的账。那笔钱像一块石头，压在你每天的计划表下面。","setFlags":["debt"],"risk":"choice"}],"evidence":{"sourceIds":[],"fictionIds":["g2-turns-fiction"]}},{"id":"ANY-LIFE-004","kind":"life","title":"家里多了一个婴儿","scene":"凌晨三点，婴儿在隔壁哭。你抱着孩子在客厅来回走，它在沙发边站着，耳朵转来转去，鼻子凑近襁褓闻了闻，又退开。奶瓶、纸尿裤和它的玩具混在一个篮子里，客厅从来没有这么挤过。","species":"any","stage":"any","requires":{"minDay":120,"notFlags":["new-baby"]},"weight":15,"cooldownDays":0,"maxPerRun":1,"choices":[{"id":"A","label":"每天留十分钟只陪它","detail":"时间很紧，但这十分钟不省。","cost":{"money":0,"energy":6,"timeHours":0.5},"effect":{"trust":5,"mood":4,"stress":-3},"outcome":"你在孩子睡着后，坐在地板上陪它十分钟。它把头搁在你腿上，没一会儿就睡着了。那十分钟后来变成你们俩的固定时间。","setFlags":["new-baby"],"followUp":{"eventId":"ANY-CHAIN-002","afterDays":365},"risk":"choice"},{"id":"B","label":"请家里人白天带它出门","detail":"把它的事分出去一部分。","cost":{"money":10,"energy":3,"timeHours":0.5},"effect":{"trust":2,"mood":2,"stress":-2},"outcome":"家里人每天下午带它出去走一圈。它回来后身上带着外面的味道，先去闻婴儿的摇篮，再趴到自己的垫子上。","setFlags":["new-baby"],"followUp":{"eventId":"ANY-CHAIN-002","afterDays":365},"risk":"choice"},{"id":"C","label":"先把它的窝挪到阳台","detail":"腾出客厅，但它会觉得自己被挪开了。","cost":{"money":0,"energy":3,"timeHours":0.5},"effect":{"trust":-2,"stress":4,"mood":-3},"outcome":"你把它的窝和饭盆挪到阳台。它在阳台门口站了很久，夜里叫了两声。第二天早上，你发现它把一只玩具叼回了客厅。","setFlags":["new-baby"],"followUp":{"eventId":"ANY-CHAIN-002","afterDays":365},"risk":"choice"}],"evidence":{"sourceIds":[],"fictionIds":["g2-turns-fiction"]}},{"id":"ANY-WONDER-001","kind":"wonder","title":"停电的夜晚","scene":"晚上八点，整栋楼突然黑了。你摸出蜡烛，火苗立起来，光在墙上晃。它本来在沙发上睡，听见火柴声抬起头，瞳孔在暗处张得很大，盯着那一点火，前爪慢慢往前挪。","species":"any","stage":"any","requires":{"minDay":3},"weight":10,"cooldownDays":60,"maxPerRun":1,"choices":[{"id":"A","label":"把蜡烛放稳，陪它看","detail":"火苗离它远一点，你坐在地板上。","cost":{"money":0,"energy":1,"timeHours":0.25},"effect":{"mood":5,"trust":3,"stress":-4},"outcome":"你把蜡烛放到它够不到的高处，坐在地板上。它仰头看那一点火，看了很久，胡须被光映成金色。蜡烛烧短一截时，它才退回沙发。","risk":"choice"},{"id":"B","label":"抱它到窗边看楼下的黑","detail":"换一个视角看这个晚上。","cost":{"money":0,"energy":3,"timeHours":0.25},"effect":{"mood":3,"trust":4,"stress":-2},"outcome":"你抱着它站在窗边。对面楼只有零星几扇窗亮着，路灯也灭了，楼下有人在说话。它把头靠在你肩上，耳朵朝声音转。","risk":"choice"},{"id":"C","label":"找出手电筒陪它玩影子","detail":"把停电变成一个游戏。","cost":{"money":0,"energy":5,"timeHours":0.5},"effect":{"mood":7,"trust":2,"stress":-3},"outcome":"你用手电筒在墙上照出一块光斑。它先是盯，然后扑上去，爪子拍在墙上。玩了十几分钟，光斑停在天花板上，它趴下来喘气。","risk":"choice"}],"evidence":{"sourceIds":[],"fictionIds":["g2-turns-fiction"]}},{"id":"ANY-ACCIDENT-001","kind":"accident","title":"门没关严","scene":"外卖送到门口，你接过袋子，门在身后没关严。等你回头，它已经站在楼道里，鼻子贴着邻居家的门缝，身体绷得很紧。楼道感应灯灭了，只剩安全出口的绿光。你听见楼下有人上来。","species":"any","stage":"any","requires":{"minDay":10},"weight":12,"cooldownDays":0,"maxPerRun":1,"choices":[{"id":"A","label":"蹲下叫它，慢慢靠近","detail":"声音压低，别把它吓跑。","cost":{"money":0,"energy":3,"timeHours":0.25},"effect":{"stress":-2,"trust":2},"outcome":"你蹲下来，叫它的名字，声音压得很低。它回头看你，犹豫了一下，往你这边走了两步。你伸手把它抱起来，它的心跳很快，爪子抓着你衣服。","risk":"choice"},{"id":"B","label":"大声喊它，快步过去","detail":"先把人弄回来再说。","cost":{"money":0,"energy":2,"timeHours":0.25},"effect":{"stress":6,"trust":-3},"outcome":"你一喊，它转身就往楼上跑。你追到半层，看见它停在拐角，身体压低。你放慢脚步，它才没有继续跑。回家后它躲了很久。","risk":"choice"},{"id":"C","label":"先关门，再拿零食引它","detail":"用熟悉的声音把它叫回来。","cost":{"money":0,"energy":4,"timeHours":0.5},"effect":{"stress":-1,"trust":3,"mood":1},"outcome":"你把门带上，回屋拿了零食袋，在门口摇。它听见声音，从楼道里探出头，一点一点靠近，最后被抱回屋里。门锁上之后，你在玄关坐了一会儿。","risk":"choice"}],"evidence":{"sourceIds":[],"fictionIds":["g2-turns-fiction"]}},{"id":"ANY-CHAIN-001","kind":"chain","title":"新家的第一夜","scene":"新家的第一夜，纸箱堆在客厅，窗帘还没挂。它绕着每个房间走了一圈，最后停在旧沙发旁边——沙发是从旧家搬来的，上面还有它留下的痕迹。楼下有车经过，灯光从没有窗帘的窗户扫进来。","species":"any","stage":"any","requires":{"minDay":60,"flags":["moved-house"]},"weight":1,"cooldownDays":0,"maxPerRun":1,"choices":[{"id":"A","label":"把旧垫子铺在床边","detail":"让它闻着熟悉的味道睡。","cost":{"money":0,"energy":2,"timeHours":0.25},"effect":{"trust":4,"mood":3,"stress":-5},"outcome":"你把旧垫子铺在床边。它闻了闻，趴上去，把下巴搁在垫子边缘。夜里你翻身，它抬起头看了一眼，又趴回去。","risk":"choice"},{"id":"B","label":"陪它在客厅坐到睡着","detail":"今晚先不睡，把它安顿好。","cost":{"money":0,"energy":5,"timeHours":1},"effect":{"trust":5,"mood":4,"stress":-4},"outcome":"你在纸箱上坐到半夜。它先是在你脚边转，后来跳上沙发，在你旁边蜷起来。你回房时它跟了进来，在床边趴下。","risk":"choice"},{"id":"C","label":"关灯，让它自己适应","detail":"总要自己习惯的。","cost":{"money":0,"energy":1,"timeHours":0},"effect":{"trust":-2,"stress":4,"mood":-2},"outcome":"你关了灯。黑暗里有爪子走动的声音，从客厅到厨房，又回来。早上你醒来，发现它睡在门口，背对着门。","risk":"choice"}],"evidence":{"sourceIds":[],"fictionIds":["g2-turns-fiction"]}},{"id":"ANY-CHAIN-002","kind":"chain","title":"窗外的烟花","scene":"除夕夜，窗外有人放烟花，光一阵一阵照进来。一声闷响过后，它抬了抬头。桌上的年夜饭还热着，你把手里的筷子放下，去看它常待的那个角落。","species":"any","stage":"any","requires":{"minDay":300},"weight":1,"cooldownDays":0,"maxPerRun":1,"choices":[{"id":"A","label":"坐到它附近","detail":"给它留出可以退开的路。","cost":{"money":0,"energy":3,"timeHours":0.5},"effect":{"trust":3,"mood":4,"stress":-2},"outcome":"你在离它两步远的地方坐下。窗帘上又亮了一下，它抬头看了看。过了一会儿，它朝你挪了半步，把下巴搁在垫子上。","risk":"choice"},{"id":"B","label":"关窗，拉上窗帘","detail":"把闪光挡在窗帘外。","cost":{"money":0,"energy":1,"timeHours":0.25},"effect":{"stress":-3,"mood":2,"trust":1},"outcome":"你关了窗，把窗帘拉拢。它趴在沙发另一头，眼睛半闭。零点时外面响成一片，它只是换了个姿势。","risk":"choice"},{"id":"C","label":"把通道腾出来","detail":"把通往窝边的纸袋收走。","cost":{"money":0,"energy":5,"timeHours":0.5},"effect":{"mood":3,"stress":0,"trust":2},"outcome":"你提走挡路的纸袋。它沿着墙根走回窝边，停下来闻了闻垫子。你端起凉下去的碗时，它还待在那里。","risk":"choice"}],"evidence":{"sourceIds":[],"fictionIds":["g2-turns-fiction"]}}]'),lf={version:af,note:cf,events:df},ff="g3-pack-1",mf="G3 来信模板：15 条；段落占位符只允许 {{name}} {{day}} {{count}} {{memory.title}} {{memory.outcome}} {{memory.day}}。",Ff=[{id:"LTR-ARRIVAL-001",scope:"on-arrival",requiresTags:[],weight:30,paragraphs:["{{name}}：","你来的第一晚，一直躲在沙发底下。我把水和饭放在不远处，关了灯，在房间里坐着等。","后来你出来了，先闻了闻碗，又绕着我走了一圈。那天的{{memory.title}}，我到现在还记得——{{memory.outcome}}","到今天，我们一起过了 {{day}} 天。第 {{memory.day}} 天，我开始习惯屋里有你的声音。","以后请多指教。"]},{id:"LTR-ARRIVAL-002",scope:"on-arrival",requiresTags:[],weight:30,paragraphs:["{{name}}：","把你带回家的那天，你在车里一直发抖，到了楼下反而不肯出来。我蹲在车门边等你，等到你自己探出头。","第一晚你睡在门口，背对着我。{{memory.title}}——{{memory.outcome}}","第 {{memory.day}} 天，我开始留意你每天什么时候醒。","到今天 {{day}} 天，门口那块地板已经被你趴出一个浅浅的印子。"]},{id:"LTR-ARRIVAL-003",scope:"on-arrival",requiresTags:[],weight:30,paragraphs:["{{name}}：","你到家时缩在航空箱的角落，水和饭都没动。我把箱子放在安静的墙角，盖了半块布，退到房间另一头。","第二天早上，饭少了一小把。{{memory.title}}——{{memory.outcome}}","第 {{memory.day}} 天，我开始能分辨你的脚步声。","到今天是 {{day}} 天。"]},{id:"LTR-MILESTONE-001",scope:"milestone",requiresTags:[],weight:20,paragraphs:["{{name}}：","写这封信的时候，窗外正好是下午的光，和你来的时候很像。到今天，我们一起过了 {{day}} 天。","我常常想起{{memory.title}}。那天{{memory.outcome}}","还有{{memory.title}}。{{memory.outcome}}","{{count}} 件小事，有些顺序我已经记不清了，但每一件发生时的光线都还在。","剩下的日子，还请多指教。"]},{id:"LTR-MILESTONE-002",scope:"milestone",requiresTags:[],weight:18,paragraphs:["{{name}}：","今年第一场雪落下来的时候，你趴在窗边看了很久。暖气片响了一声，你的耳朵就转过去。","我记得{{memory.title}}。{{memory.outcome}}","还有{{memory.title}}。{{memory.outcome}}","冬天还长。我把你的垫子挪到了暖气旁边，夜里听见你翻身，就知道你睡得好。"]},{id:"LTR-MILESTONE-003",scope:"milestone",requiresTags:[],weight:16,paragraphs:["{{name}}：","第 {{day}} 天。今天没发生什么特别的事：你吃了饭，睡了两觉，在屋里走了一圈。","{{memory.title}}，那件事之后，屋子里有些东西变了。{{memory.outcome}}","{{memory.title}}。{{memory.outcome}}","{{count}} 件事里，大部分都是这样的小事。我把它们都记着。"]},{id:"LTR-MILESTONE-004",scope:"milestone",requiresTags:["multipet"],weight:14,paragraphs:["{{name}}：","家里不止你一个的时候，我总担心你们处不好。现在看，担心是多余的——你们有自己的规矩。","{{memory.title}}。{{memory.outcome}}","{{memory.title}}。{{memory.outcome}}","{{count}} 件事里，有一半是你们俩一起弄出来的。"]},{id:"LTR-MILESTONE-005",scope:"milestone",requiresTags:[],weight:18,paragraphs:["{{name}}：","你最近爱在下午打盹。早上我起床时你还没醒，等我洗漱完，你才慢慢从垫子上站起来。","{{memory.title}}。{{memory.outcome}}","{{memory.title}}。{{memory.outcome}}","我不催你。{{count}} 件事，我们一件一件地过。"]},{id:"LTR-FAREWELL-001",scope:"farewell",requiresTags:[],weight:30,paragraphs:["{{name}}：","这段时间我一直在想，该怎么把日子过慢一点。你的饭量小了，走路也慢，但每天还是会在门口等我。","{{memory.title}}。{{memory.outcome}}","{{memory.title}}。{{memory.outcome}}","剩下的时间，我想多在家待着。{{count}} 件事，我们慢慢想。"]},{id:"LTR-FAREWELL-002",scope:"farewell",requiresTags:[],weight:26,paragraphs:["{{name}}：","今天你在我腿上睡了很久，久到我腿麻了也没动。窗外有风，窗帘一下一下地碰着窗台。","{{memory.title}}。{{memory.outcome}}","{{memory.title}}。{{memory.outcome}}","我不知道还能这样过多少个下午。{{day}} 天了，谢谢你。"]},{id:"LTR-FAREWELL-003",scope:"farewell",requiresTags:[],weight:26,paragraphs:["{{name}}：","我把你的旧垫子洗了，晾在阳台上。你站在旁边看，等它干了就趴上去，像是确认它还是原来那块。","{{memory.title}}。{{memory.outcome}}","{{memory.title}}。{{memory.outcome}}","有些东西旧了也还能用。{{count}} 件事之后，我们还是我们。"]},{id:"LTR-AFTER-001",scope:"after-death",requiresTags:[],weight:30,paragraphs:["{{name}}：","你已经不在这个屋子里了。我还是会在下午抬头看窗台，然后又想起来。","我记得{{memory.title}}。{{memory.outcome}}","第 {{memory.day}} 天，{{memory.title}}。{{memory.outcome}}","我们在一起 {{count}} 件事。谢谢你愿意来这里。"]},{id:"LTR-AFTER-002",scope:"after-death",requiresTags:[],weight:26,paragraphs:["{{name}}：","这几天我整理柜子，翻出你的旧玩具。上面的牙印还在，我拿在手里看了一会儿，又放回原处。","{{memory.title}}。{{memory.outcome}}","{{memory.title}}。{{memory.outcome}}","屋子里安静了很多。{{count}} 件事，我都记得。"]},{id:"LTR-AFTER-003",scope:"after-death",requiresTags:[],weight:24,paragraphs:["{{name}}：","今天下楼，看见一只和你很像的动物，站在树底下。我站住了，它也看了我一眼，然后走开。","{{memory.title}}。{{memory.outcome}}","{{memory.title}}。{{memory.outcome}}","回家的路上我想，{{count}} 件事里，你最常做的那个动作，我大概会记很久。"]},{id:"LTR-AFTER-004",scope:"after-death",requiresTags:[],weight:24,paragraphs:["{{name}}：","我把你的垫子收进了柜子最上层，没有扔。偶尔会拿出来晒一晒，再放回去。","{{memory.title}}。{{memory.outcome}}","{{memory.title}}。{{memory.outcome}}","第 {{day}} 天了。我还是会在开门的时候，先听一下有没有爪子声。"]}],Ef={version:ff,note:mf,letters:Ff},hf="g3-params-2",pf={scope:"G3-GAMEPLAY 校准参数。所有数值依据 docs/v4.5-parallel-development/gameplay/sim/g3-sim.mjs 的 180 局确定性模拟（3 人生 × 3 物种 × 10 seed × 2 档位），结论见同目录 G3-BALANCE.md 与 G3-SIM-RESULTS.json。未做真人时长验证；分钟档位标签沿用 G2 结构，未经真人校准。",weightsSemantics:"事件有效权重 = event.weight × (weights.kind[event.kind] / 10) × (event.stage 匹配当前动物阶段时 × weights.stageBias[阶段])。kind 取 10 = 中性（不放大不压制）；stageBias 取 1.0 = 中性。kind 只做相对调节，事件自身 weight 仍是主导。",statsSemantics:"stats.initial 为动物入场初始值（0..100）。careTrust/careMood/observeTrust/comfortTrust/restMood 对应 v45-core 行动的状态增量；dayStress 为每节拍动物压力自然上浮，stressDecay 为每节拍自然回落，净漂移 = dayStress - stressDecay。",economySemantics:"与 v45-core/src/journey.ts 的 economy 字段一一对应：每节拍恢复 recoveryEnergy/recoveryHours（上限 100/hoursCap），work 每个节拍日至多一次；care 每只动物每局一次（journey.ts 的 cared 不复位）；respond 在 incident 出现的节拍日内完成，否则下一里程碑结算死亡。",disclaimer:"数值为模拟结论，不是拍脑袋，也不是「已平衡」——未跑真人。"},yf={pay:24,workEnergy:18,workHours:3,restEnergy:24,recoveryEnergy:12,recoveryHours:3,hoursCap:10,careMoney:8,careEnergy:7,careHours:1,prepareMoney:6,prepareHours:1,responseMoney:24,responseHours:2,_why:{pay:"维持 G2 值 24：180 主批局（engaged）+ 72 变体局共 252 局 0 次资金归零、0 次 respond 付不起。engaged 每局打工 3.7-4.5 次即可覆盖全部刚性支出（respond 24×2 + care 8×2 + prepare 6 + life 事件 30-60×2-4），末态资金均值 ~93（p10-p90：71-130）；囤积（>250）只出现在贪婪策略（自选行为）。上调会让钱更不值钱，下调会逼近 respond 线引发锁死。",workEnergy:"15→18：G2 值 15 与每拍恢复量相等，纯打工流精力永不下降（首轮模拟 rest 使用率为 0，精力轴形同虚设）。提到 18 后打工净耗 6/拍：engaged 策略下打工受钱约束（rest 仍 0），贪婪策略（有钱就打）下 rest 升至 2.6-3.6 次/局，精力轴对重度玩家产生真实取舍；respond 不耗精力，故 252 局仍 0 锁死。",workHours:"G2 值 3h：时间是最紧的资源（恢复 3/拍、上限 10），工作是时间最大去向，与 care(1h)+事件(0-3h) 形成每拍 4-7h 的真实竞争。",restEnergy:"G2 值 24：一次休息≈2 拍恢复，爆发回血定位不变。",recoveryEnergy:"15→12：G2 值 15 时 21%-30% 的节点精力顶满 100（恢复被浪费）。12 之后顶满率降至 10%（15m）/22%（30m），精力在 40-98 区间活动（p10-p90 轨迹见 G3-SIM-RESULTS.json），打工流需要穿插休息。",recoveryHours:"G2 值 3/拍，配 hoursCap=10 构成时间压力主轴：每拍刚性支出（respond 2h/care 1h/work 3h）+ 事件 0-3h 即接近恢复量，实测 21%-30% 节点时间顶满、偶发短缺，是三资源中唯一始终有取舍感的轴，不动。",hoursCap:"G2 值 10：3 项重行动（work3+care1+事件3h）即达上限 70%，留出「想做但做不完」的窗口。",careMoney:"G2 值 8，每动物每局一次（journey.ts cared 不复位），是「前期小投入换 illness 分支豁免」的钩子，实测全部 90+ 局都做了（性价比明确）。若要更纠结可提至 12，属后续调参点。",careEnergy:"G2 值 7：与 work 18 合计 25，超过单拍恢复 12，同拍做两者需要前拍攒精力或休息。",careHours:"G2 值 1。",prepareMoney:"G2 值 6，一次性换 accident 分支豁免。实测策略总会买；真实性价比偏高（6 元免 24 元 respond + 死亡风险），如要削弱可提到 10，属后续调参点，先维持 G2 兼容。",prepareHours:"G2 值 1。",responseMoney:"G2 值 24 = 一整拍打工收入，incident 的核心代价。模拟中 180 局 0 次付不起（见破产率 0），量级成立。",responseHours:"G2 值 2：与时间缓冲 2h 匹配，策略「花时间必留 2h」即可保证 respond 可用。"}},gf={"15m":{intervals:[2,12,31,87,180,410,690,1040],freezeAfterBeat:6,incidentAtBeat:2,firstEncounterDays:3,anotherEncounterDays:10,_why:{intervals:"8 拍、总跨度 2452 天（约 6.7 年）。沿用 G2 曲线（先密后疏），保证前两拍是短跳（2/12 天）、「第一周的选择」可见；满足 runtime-constraints 的 calendarSpan 约束（2+12+6 ≤ 2200）。",freezeAfterBeat:"第 6 拍（约第 722 天）停止新相遇，留 2 拍收束，与 G2 一致。",incidentAtBeat:"第 2 拍（第 14 天）出突发，此时玩家已有 1-2 拍准备期（可 prepare/care）。",firstEncounterDays:"G2 值 3：拒绝后近期再来一次。",anotherEncounterDays:"G2 值 10：第二只在第 10 天附近出现，处于第 1-2 拍之间，不挤压开场。"}},"30m":{intervals:[2,5,13,23,40,68,117,165,214,333,470,590,710,890],freezeAfterBeat:11,incidentAtBeat:4,firstEncounterDays:3,anotherEncounterDays:12,_why:{intervals:"14 拍、总跨度 3640 天（约 10 年）。沿用 G2 曲线；minDay=60/90/120/200 的 life 事件分别在第 3/4/5/6 拍后可达，分散在 30m 的中后段。",freezeAfterBeat:"第 11 拍冻结，与 G2 一致。",incidentAtBeat:"第 4 拍（第 40 天）出突发，比 15m 晚，因为 30m 前期跳步更密。",firstEncounterDays:"G2 值。",anotherEncounterDays:"G2 值 12。"}}},Cf={kind:{daily:7,turn:11,autonomy:11,multipet:9,chain:10,accident:10,wonder:8,life:12,_why:{daily:"10→7：daily 事件自身 weight 已是池中最高（20-30），中性权重下 daily 份额超 50%（超出 docs 04 §5.3 的 40% 候选配额）。压到 7 后实测份额 40%（15m）/ 43%（30m），对齐配额，并把节点让给 turn/chain/life，降低两局事件集的重叠。",turn:"11：物种习性转折是可感差异的主要来源，略放大。",autonomy:"10→11：低频但便宜（多为 0 成本选项），多露面不伤经济。",multipet:"9：受 minAnimals=2 门槛自然限制，出现即不稀疏，略压。",chain:"9→10：链式事件主要由 followUp 到期直出（不抽签），抽签池里略升让链源更容易被抽到（followUp 触发率 94%/96% 是本档亮点，值得保）。",accident:"9→10：与 journey.ts 的 incident 机制并行，先维持中性偏上观察（实测无双重叠加事故锁死）。",wonder:"7→8：奇遇事件少（池中 1-2 条），配额目标 ~5%，略升避免整局见不到。",life:"12：人生舞台是本作主轴，且 life 事件多被 minDay 门槛压制（60/90/120/200 天），中后段才可选，实测每局 2.2 条（15m）/ 3.7 条（30m）、份额 15%，量级合适。"}},stageBias:{kitten:1.2,young:1.1,adult:1,senior:1.15,_why:{kitten:"幼年期事件密度略升（1.2），入场适应期内容优先露出。",young:"1.1 略升。",adult:"1.0 中性基准。",senior:"1.15：老年段节拍稀疏（跳步大），略升权重让老年内容在少数节拍里露面。"}}},Af={initial:{health:70,mood:50,trust:25,stress:25},careTrust:5,careMood:3,observeTrust:.5,comfortTrust:5,dayStress:2,stressDecay:0,restMood:2,_why:{"initial.health":"70：入场健康留有波动空间（事故事件 -2~-3、照护 +2、恢复 +10）。","initial.mood":"60→50：事件与 care 的正向效应密集（每个事件节点都可能有 +2~+5），60 起步时首轮终局 mood 均值 90-99（饱和、无差异）。50 起步后终局 77（15m）/94（30m）；30m 的饱和来自事件密度（双动物 ~25 节点），见 G3-BALANCE.md 内容侧建议。","initial.trust":"30→25：新到家的动物信任偏低（new_arrival 语义）。终局对投入度敏感——满投入 79（15m）/96（30m），低投入策略 46/65，信任轴有区分度；30 起步时（首轮）满投入终局 95-100（无差异）。","initial.stress":"20→25：给 dayStress 净漂移留空间，终局压力 33-40（engaged/lazy/greedy 三种策略均落在此区间）。",careTrust:"G2 候选 5：一次正式照料 +5 信任。每动物每局只有一次，不构成饱和源。",careMood:"4→3：mood 饱和主因是「事件正效应×节点数」，行动侧先降 1 点，保留 care 的信任主导定位。",observeTrust:"1→0.5：observe 是免费轻互动、每个事件节点都可做一次，1/次 × 14-25 节点 = +14-25 信任，是信任饱和的最大单一来源（首轮终局 95-100）。0.5/次后低投入玩家终局信任 46-65，与满投入（79-96）拉开差距。",comfortTrust:"6→5：comfort 免费且只在 incident/末拍可用，是最强信任手段，5 保持其显著高于 care（5）但不再叠加成饱和源。",dayStress:"G2 候选 2/拍（按事件节点计）：净压力上浮来源。配 stressDecay=0 后每节点净 +2。",stressDecay:"1→0：带衰减 1 时首轮终局压力均值 8-11（贴地）——事件选项里减压分支多，衰减让压力单调下行。去掉衰减后终局 33-40，压力成为需要管理的轴。若 Content 后续把事件减压效应收窄，可重新启用衰减。",restMood:"4→2：与 careMood 同理压低行动侧情绪增量，让事件选择主导 mood 曲线。"}},Bf={version:hf,NOTES:pf,economy:yf,pace:gf,weights:Cf,stats:Af},tt=t5({events:lf,letters:Ef,params:Bf});if(!tt.ok)throw new Error(tt.errors.join(`
